package com.menaphite;

import java.awt.Color;
import net.runelite.api.Constants;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxPriority;
import net.runelite.client.util.ImageUtil;

final class BoostDecayInfoBox extends InfoBox
{
	private int tick = -1;
	private int remaining;
	private long tickMillis;

	BoostDecayInfoBox(Plugin plugin)
	{
		super(ImageUtil.loadImageResource(Plugin.class, "/net/runelite/client/plugins/boosts/buffed.png"), plugin);
		setPriority(InfoBoxPriority.MED);
		setTooltip("Next buff change");
	}

	void update(int now, int ticks)
	{
		if (now != tick)
		{
			tick = now;
			tickMillis = System.currentTimeMillis();
		}
		remaining = ticks;
	}

	@Override
	public String getText()
	{
		long millis = remaining * Constants.GAME_TICK_LENGTH - (System.currentTimeMillis() - tickMillis);
		long seconds = Math.max(0, millis / 1000);
		return seconds < 10 ? "0" + seconds : Long.toString(seconds);
	}

	@Override
	public Color getTextColor()
	{
		return remaining < 10 ? Color.RED : Color.WHITE;
	}
}

package com.menaphite;

/** An observed combat decay boundary, advanced using game ticks rather than wall time. */
final class CombatDecayCycle
{
	private int lastTick = -1;
	private boolean known;
	int age;
	int preserveTicks;
	private boolean preserveInCycle;

	void observe(int tick)
	{
		known = true;
		age = 0;
		lastTick = tick;
		preserveInCycle = preserveTicks > 0;
	}

	int logoutSegment()
	{
		return known && !preserveInCycle && age < 100 ? age / 20 : -1;
	}

	void restore(int segment, int tick)
	{
		reset();
		if (segment < 0 || segment > 4) { return; }
		observe(tick);
		age = segment * 20;
	}

	void advance(int tick, boolean preserve)
	{
		if (lastTick >= 0)
		{
			for (int i = lastTick; i < tick; i++) { step(preserve); }
		}
		lastTick = tick;
	}

	boolean step(boolean preserve)
	{
		preserveTicks = preserve ? Math.min(25, preserveTicks + 1) : 0;
		preserveInCycle |= preserve;
		if (!known) { return false; }
		age++;
		if (age == 150 || ((age == 100 || age == 125) && preserveTicks < 25))
		{
			age = 0;
			preserveInCycle = preserve;
			return true;
		}
		return false;
	}

	boolean known() { return known; }

	CombatDecayCycle copy()
	{
		CombatDecayCycle copy = new CombatDecayCycle();
		copy.known = known;
		copy.age = age;
		copy.preserveTicks = preserveTicks;
		copy.preserveInCycle = preserveInCycle;
		return copy;
	}

	void reset()
	{
		known = false;
		lastTick = -1;
		age = 0;
		preserveTicks = 0;
		preserveInCycle = false;
	}
}

package com.menaphite;

import java.util.function.Predicate;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import static net.runelite.api.Skill.*;
import net.runelite.api.gameval.VarbitID;

enum Effect
{
	SATURATED_HEART("Saturated heart", VarbitID.SATURATED_HEART_TIME, MenaphiteRemedyRemindersConfig::saturatedHeart, MAGIC),
	DIVINE_SUPER_COMBAT("Divine super combat", VarbitID.DIVINECOMBAT_POTION_TIME, MenaphiteRemedyRemindersConfig::divineSuperCombat, ATTACK, STRENGTH, DEFENCE),
	DIVINE_SUPER_ATTACK("Divine super attack", VarbitID.DIVINEATTACK_POTION_TIME, MenaphiteRemedyRemindersConfig::divineSuperAttack, ATTACK),
	DIVINE_SUPER_STRENGTH("Divine super strength", VarbitID.DIVINESTRENGTH_POTION_TIME, MenaphiteRemedyRemindersConfig::divineSuperStrength, STRENGTH),
	DIVINE_SUPER_DEFENCE("Divine super defence", VarbitID.DIVINEDEFENCE_POTION_TIME, MenaphiteRemedyRemindersConfig::divineSuperDefence, DEFENCE),
	DIVINE_RANGING("Divine ranging", VarbitID.DIVINERANGE_POTION_TIME, MenaphiteRemedyRemindersConfig::divineRanging, RANGED),
	DIVINE_BASTION("Divine bastion", VarbitID.DIVINEBASTION_POTION_TIME, MenaphiteRemedyRemindersConfig::divineBastion, RANGED, DEFENCE),
	DIVINE_BATTLEMAGE("Divine battlemage", VarbitID.DIVINEBATTLEMAGE_POTION_TIME, MenaphiteRemedyRemindersConfig::divineBattlemage, MAGIC, DEFENCE);

	final String displayName;
	final int varbit;
	private final Predicate<MenaphiteRemedyRemindersConfig> enabled;
	private final Skill[] skills;

	Effect(String displayName, int varbit, Predicate<MenaphiteRemedyRemindersConfig> enabled, Skill... skills)
	{
		this.displayName = displayName;
		this.varbit = varbit;
		this.enabled = enabled;
		this.skills = skills;
	}

	static boolean meetsMinimum(Client client, MenaphiteRemedyRemindersConfig config, Skill skill)
	{
		int minimum;
		switch (skill)
		{
			case ATTACK: minimum = config.minimumAttack(); break;
			case STRENGTH: minimum = config.minimumStrength(); break;
			case DEFENCE: minimum = config.minimumDefence(); break;
			case RANGED: minimum = config.minimumRanged(); break;
			case MAGIC: minimum = config.minimumMagic(); break;
			default: minimum = config.minimumPreserveBoost(); break;
		}
		return client.getBoostedSkillLevel(skill) - client.getRealSkillLevel(skill) >= Math.max(1, minimum);
	}

	boolean hasBoost(Client client, MenaphiteRemedyRemindersConfig config)
	{
		for (Skill skill : skills)
		{
			if (meetsMinimum(client, config, skill)) { return true; }
		}
		return false;
	}

	boolean enabled(MenaphiteRemedyRemindersConfig config)
	{
		return enabled.test(config);
	}

	static Effect forVarbit(int varbit)
	{
		for (Effect effect : values())
		{
			if (effect.varbit == varbit) { return effect; }
		}
		return null;
	}

	boolean covers(Effect effect)
	{
		if (this == DIVINE_SUPER_COMBAT)
		{
			return effect == DIVINE_SUPER_ATTACK || effect == DIVINE_SUPER_STRENGTH || effect == DIVINE_SUPER_DEFENCE;
		}
		if (this == DIVINE_BASTION)
		{
			return effect == DIVINE_RANGING || effect == DIVINE_SUPER_DEFENCE;
		}
		return this == DIVINE_BATTLEMAGE && effect == DIVINE_SUPER_DEFENCE;
	}
}

