		super(image, plugin);
		this.effect = effect;
	}

	void update(int ticks)
	{
		seconds = ReminderTimers.secondsRemaining(ticks);
		setTooltip("Drink a Menaphite remedy<br>" + effect.displayName + ": " + seconds + "s remaining");
