	public void mixedStatsDivinesAndHeartsDispatchOnlyEligiblePrompts() throws Exception
	{
		wirePlugin();
		doReturn(18).when(config).minimumStrength();
		doReturn(18).when(config).minimumDefence();
		doReturn(true).when(config).preserveDefence();
		doReturn(true).when(config).saturatedHeart();
		doReturn(false).when(config).heartOnlyWhenBanked();
		doReturn(false).when(config).showInfobox();
		ItemContainer inventory = mock(ItemContainer.class);
		when(inventory.contains(ItemID._4DOSESTATRENEWAL)).thenReturn(true);
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		Skill[] skills = {Skill.RANGED, Skill.STRENGTH, Skill.DEFENCE, Skill.MAGIC};
		int[] boost = new int[Skill.values().length];
		for (Skill skill : skills)
		{
			when(client.getRealSkillLevel(skill)).thenReturn(99);
			when(client.getBoostedSkillLevel(skill)).thenAnswer(invocation -> 99 + boost[skill.ordinal()]);
		}
		java.util.Map<Integer, Integer> timers = new java.util.HashMap<>();
		when(client.getVarbitValue(anyInt())).thenAnswer(i -> timers.getOrDefault(i.getArgument(0), 0));
		timers.put(VarbitID.PRAYER_PRESERVE_UNLOCKED, 1);
		int[] divine = {VarbitID.DIVINERANGE_POTION_TIME, VarbitID.DIVINESTRENGTH_POTION_TIME, VarbitID.DIVINEDEFENCE_POTION_TIME};
		int[] minimum = {11, 18, 18, 8};
		for (int strong = 0; strong < 16; strong++)
		{
			for (int protectedMask = 0; protectedMask < 8; protectedMask++)
			{
				for (int heart = 0; heart <= 2; heart++) // none, imbued, saturated
				{
					for (int i = 0; i < skills.length; i++)
					{
						boost[skills[i].ordinal()] = minimum[i] - ((strong & (1 << i)) == 0 ? 1 : 0);
						if (i < 3) { timers.put(divine[i], (protectedMask & (1 << i)) == 0 ? 0 : 8); }
					}
					timers.put(VarbitID.IMBUED_HEART_TIMER, heart == 0 ? 0 : 1);
					timers.put(VarbitID.SATURATED_HEART_TIME, heart == 2 ? 8 : 0);
					int protectedSkills = protectedMask | (heart == 2 ? 8 : 0);
					clearInvocations(overhead);
					plugin.startUp();
					plugin.onGameTick(new GameTick());
					verify(overhead, times((strong & protectedSkills) == 0 ? 0 : 1)).show();
					verify(overhead, times((strong & ~protectedSkills) == 0 ? 0 : 1)).showPreserve();
					plugin.shutDown();
				}
			}
		}
	}

	@Test
	public void exhaustiveSipWindowsUseTheFullPlanningHorizon() throws Exception
	{
		assertEquals(5, config.remindSeconds());
		for (int seconds : new int[]{5, 6, 8, 10})
		{
			int lead = ReminderTimers.reminderTicks(seconds);
			long[] results = sipWindowOutcomes(seconds, 150, true);
			assertEquals(100L * (lead + 1) * (lead + 1), results[3]);
			assertEquals(599 - lead, results[0]);
			assertEquals(623.5 - lead, (double) results[2] / results[3], 0.0);
			assertEquals(648 - lead, results[1]);
		}
		// Emulate the old gate by withholding planning until target - (150 - lead).
		long[] old = sipWindowOutcomes(10, 150 - ReminderTimers.reminderTicks(10), false);
		assertEquals(532, old[0]);
	}

	private long[] sipWindowOutcomes(int seconds, int horizon, boolean invariant) throws Exception
	{
		int expiry = 500;
		int lead = ReminderTimers.reminderTicks(seconds);
		int target = expiry - lead - 1;
		long min = Long.MAX_VALUE, max = Long.MIN_VALUE, sum = 0, count = 0;
		long shortestAfterSip = Long.MAX_VALUE, longestAfterSip = 0, totalAfterSip = 0;
		Field field = PreserveReminder.class.getDeclaredField("cycle");
		field.setAccessible(true);
		doReturn(seconds).when(config).remindSeconds();
		int[] now = {0};
		int[] promptedAt = {-1};
		when(client.getTickCount()).thenAnswer(ignored -> now[0]);
		doAnswer(ignored -> { promptedAt[0] = now[0]; return null; }).when(overhead).showPreserve();
		for (int phase = 0; phase < 100; phase++)
		{
			// Keep mock invocation history bounded across this exhaustive simulation.
			clearInvocations(client, config, overhead, boxes, notifier, settings);
			reminder.reset();
			promptedAt[0] = -1;
			CombatDecayCycle tracked = (CombatDecayCycle) field.get(reminder);
			tracked.observe(0);
			tracked.age = phase; // Phase at the start of the five-minute protected boost.
			for (now[0] = target - horizon; now[0] < target && promptedAt[0] < 0; now[0]++)
			{
				reminder.tick(plugin, target);
			}
			assertTrue("No activation prompt for phase " + phase, promptedAt[0] >= 0);
			for (int reaction = 0; reaction <= lead; reaction++)
			{
				int activation = promptedAt[0] + reaction;
				int firstEndpoint = -1;
				for (int sip = target; sip < expiry; sip++)
				{
					CombatDecayCycle simulation = new CombatDecayCycle();
					simulation.observe(0);
					simulation.age = phase;
					int endpoint = -1;
					for (int tick = 1; tick <= expiry + 150; tick++)
					{
						// Activation at tick A affects intervals after A, matching PreservePlan.
						boolean decay = simulation.step(tick > activation);
						// Earlier decays still reset the cycle, but the boost protects the stat.
						if (decay && tick >= sip) { endpoint = tick; break; }
					}
					assertTrue("Missing decay", endpoint >= sip);
					if (firstEndpoint < 0) { firstEndpoint = endpoint; }
					if (invariant)
					{
						assertTrue("Decay inside the permitted sip window", endpoint >= expiry);
						assertEquals("Sip timing changed endpoint for phase " + phase
							+ ", reaction " + reaction + ", sip " + sip, firstEndpoint, endpoint);
					}
					min = Math.min(min, endpoint);
					max = Math.max(max, endpoint);
					sum += endpoint;
					int afterSip = endpoint - sip;
					shortestAfterSip = Math.min(shortestAfterSip, afterSip);
					longestAfterSip = Math.max(longestAfterSip, afterSip);
					totalAfterSip += afterSip;
					count++;
				}
			}
		}
		System.out.println("Sip window " + seconds + "s; horizon=" + horizon + "; outcomes=" + count
			+ "; seconds after sip min/mean/max=" + shortestAfterSip * 0.6 + "/"
			+ totalAfterSip * 0.6 / count + "/" + longestAfterSip * 0.6);
		return new long[]{min, max, sum, count};
	}

