		when(player.getCanvasTextLocation(eq(graphics), eq("Custom reminder"), anyInt())).thenReturn(new Point(10, 20));
		ReminderOverhead overhead = new ReminderOverhead(client, config);
		overhead.show();
		overhead.render(graphics);
